use super::super::primitives::Color4;
use crate::color::D3Color;
use std::sync::Arc;

/// Convert D3Color + opacity to Color4
pub(super) fn to_color4(color: &D3Color, opacity: f32) -> Color4 {
    // Use D3Color fields directly (they're already f32 in [0,1] range)
    [color.r, color.g, color.b, color.a * opacity]
}

/// Clip a line segment to the unit rectangle [0,1] x [0,1] using Cohen-Sutherland algorithm
/// Returns Some((x0, y0, x1, y1)) if the clipped segment is visible, None if entirely outside
pub(super) fn clip_line_segment(
    x0: f32,
    y0: f32,
    x1: f32,
    y1: f32,
) -> Option<(f32, f32, f32, f32)> {
    const INSIDE: u8 = 0;
    const LEFT: u8 = 1;
    const RIGHT: u8 = 2;
    const BOTTOM: u8 = 4;
    const TOP: u8 = 8;

    fn compute_outcode(x: f32, y: f32) -> u8 {
        let mut code = INSIDE;
        if x < 0.0 {
            code |= LEFT;
        } else if x > 1.0 {
            code |= RIGHT;
        }
        if y < 0.0 {
            code |= TOP;
        } else if y > 1.0 {
            code |= BOTTOM;
        }
        code
    }

    let mut x0 = x0;
    let mut y0 = y0;
    let mut x1 = x1;
    let mut y1 = y1;
    let mut outcode0 = compute_outcode(x0, y0);
    let mut outcode1 = compute_outcode(x1, y1);

    loop {
        if (outcode0 | outcode1) == 0 {
            return Some((x0, y0, x1, y1));
        } else if (outcode0 & outcode1) != 0 {
            return None;
        } else {
            let outcode_out = if outcode0 != 0 { outcode0 } else { outcode1 };
            let (x, y);

            if (outcode_out & TOP) != 0 {
                x = x0 + (x1 - x0) * (0.0 - y0) / (y1 - y0);
                y = 0.0;
            } else if (outcode_out & BOTTOM) != 0 {
                x = x0 + (x1 - x0) * (1.0 - y0) / (y1 - y0);
                y = 1.0;
            } else if (outcode_out & RIGHT) != 0 {
                y = y0 + (y1 - y0) * (1.0 - x0) / (x1 - x0);
                x = 1.0;
            } else {
                y = y0 + (y1 - y0) * (0.0 - x0) / (x1 - x0);
                x = 0.0;
            }

            if outcode_out == outcode0 {
                x0 = x;
                y0 = y;
                outcode0 = compute_outcode(x0, y0);
            } else {
                x1 = x;
                y1 = y;
                outcode1 = compute_outcode(x1, y1);
            }
        }
    }
}

use gpui::SharedString;

/// Format a tick value using the optional custom formatter.
///
/// Returns a `SharedString` so formatted labels can be cached and reused by
/// GPU renderers without repeated per-frame `String` allocations.
pub(super) fn format_tick(value: f64, formatter: &Option<fn(f64) -> String>) -> SharedString {
    match formatter {
        Some(f) => f(value).into(),
        None => {
            if value.abs() < 1e-10 {
                "0".into()
            } else if value.abs() >= 1000.0 || value.abs() < 0.01 {
                format!("{:.1e}", value).into()
            } else if value.fract().abs() < 1e-10 {
                format!("{:.0}", value).into()
            } else {
                format!("{:.1}", value).into()
            }
        }
    }
}

pub(super) fn normalize_value(value: f64, min: f64, max: f64) -> f64 {
    if (max - min).abs() < 1e-10 {
        0.5
    } else {
        (value - min) / (max - min)
    }
}

pub(super) fn get_contour_color(
    t: f64,
    color_scale: &Option<Arc<dyn Fn(f64) -> D3Color + Send + Sync>>,
    default_color: &D3Color,
    opacity: f32,
) -> Color4 {
    let color = if let Some(scale) = color_scale {
        scale(t)
    } else {
        *default_color
    };
    to_color4(&color, opacity)
}
